#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "nussinov.hpp"

using num_t = DATA_TYPE;
using base  = char;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

/**
 * Layout tuning – mirrors the way C arrays are indexed:
 *   seq[i]
 *   table[i][j]
 */
struct tuning {
	DEFINE_PROTO_STRUCT(seq_layout,   i_vec);
	DEFINE_PROTO_STRUCT(table_layout, j_vec ^ i_vec);
} tuning;

// scoring helpers (C macros -> C++ functions)
inline num_t max_score(num_t s1, num_t s2) {
	return (s1 >= s2) ? s1 : s2;
}

inline num_t match_score(base b1, base b2) {
	return ((b1 + b2) == 3) ? num_t(1) : num_t(0);
}

// initialization function
void init_array(std::size_t n, auto seq, auto table) {
	using namespace noarr;

	// base is AGCT/0..3
	traverser(seq).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		seq[state] = static_cast<base>((i + 1) % 4);
	});

	// table is zero-initialized
	traverser(table).for_each([=](auto state) {
		table[state] = num_t(0);
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_nussinov(int n, auto seq, auto table) {
	using namespace noarr;
	(void)n; // we derive sizes from the structure

	// length of the sequence / table dimension
	auto len = table | get_length<'i'>();

	// auxiliary 1D structure to drive the 'k' loop via a traverser
	auto k_struct = scalar<char>() ^ vector<'k'>(len);

#pragma scop
	// outer loop over i, emulating i from len-1 down to 0
	traverser(table).template for_dims<'i'>([=](auto outer) {
		// 'outer' iterates i in ascending order; map it to descending
		auto outer_state = outer.state();
		std::size_t iter = get_index<'i'>(outer_state); // 0 .. len-1
		std::size_t i = len - 1 - iter;                 // len-1 .. 0

		std::size_t j_start = i + 1;
		if (j_start >= len)
			return; // no j for this i (matches original loop guard)

		std::size_t j_len = len - j_start;

		// inner loop over j: j = i+1 .. len-1
		auto trav_j = traverser(table).order(
			noarr::fix<'i'>(i) ^
			noarr::shift<'j'>(j_start) ^
			noarr::set_length<'j'>(j_len)
		);

		trav_j.for_each([=](auto j_state) {
			// local j index (0 .. j_len-1) -> global j
			std::size_t j_local = get_index<'j'>(j_state);
			std::size_t j       = j_start + j_local;

			// table[i][j]
			num_t tij = table[noarr::idx<'i', 'j'>(i, j)];

			// if (j-1 >= 0) table[i][j] = max(table[i][j], table[i][j-1]);
			if (j > 0) {
				tij = max_score(tij, table[noarr::idx<'i', 'j'>(i, j - 1)]);
			}

			// if (i+1 < N) table[i][j] = max(table[i][j], table[i+1][j]);
			if (i + 1 < len) {
				tij = max_score(tij, table[noarr::idx<'i', 'j'>(i + 1, j)]);
			}

			// if (j-1 >= 0 && i+1 < N) { ... }
			if (j > 0 && i + 1 < len) {
				num_t t_ip1_jm1 = table[noarr::idx<'i', 'j'>(i + 1, j - 1)];

				// don't allow adjacent elements to bond
				if (i < j - 1) {
					num_t cand = t_ip1_jm1
						+ match_score(
							seq[noarr::idx<'i'>(i)],
							seq[noarr::idx<'i'>(j)]
						  );
					tij = max_score(tij, cand);
				} else {
					tij = max_score(tij, t_ip1_jm1);
				}
			}

			// for (k = i+1; k < j; k++)
			//   table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
			if (j > i + 1) {
				std::size_t k_start = i + 1;
				std::size_t k_len   = j - k_start;

				auto trav_k = traverser(k_struct).order(
					noarr::shift<'k'>(k_start) ^
					noarr::set_length<'k'>(k_len)
				);

				trav_k.for_each([&](auto k_state) {
					std::size_t k_local = get_index<'k'>(k_state);
					std::size_t k       = k_start + k_local;

					num_t cand =
						table[noarr::idx<'i', 'j'>(i,     k)] +
						table[noarr::idx<'i', 'j'>(k + 1, j)];
					tij = max_score(tij, cand);
				});
			}

			// write back result for (i, j)
			table[noarr::idx<'i', 'j'>(i, j)] = tij;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// data
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto seq = noarr::bag(noarr::scalar<base>()   ^ tuning.seq_layout   ^ set_lengths);
	auto table = noarr::bag(noarr::scalar<num_t>() ^ tuning.table_layout ^ set_lengths);

	// initialize data
	init_array(n, seq.get_ref(), table.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_nussinov(static_cast<int>(n), seq.get_ref(), table.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (forces evaluation / prevents DCE)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, table.get_ref() ^ noarr::hoist<'i'>());
	}

	// print time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

