#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "nussinov.hpp"

using num_t = DATA_TYPE;
using base = char;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	DEFINE_PROTO_STRUCT(seq_layout, i_vec);
	DEFINE_PROTO_STRUCT(table_layout, j_vec ^ i_vec);
} tuning;

// match(b1, b2) = 1 if bases can pair, 0 otherwise (b in {0,1,2,3}, A/G/C/T)
inline num_t match_base(base b1, base b2) {
	int v1 = static_cast<unsigned char>(b1);
	int v2 = static_cast<unsigned char>(b2);
	return (v1 + v2 == 3) ? num_t(1) : num_t(0);
}

// Array initialization.
void init_array(auto seq, auto table) {
	using namespace noarr;

	// seq: i
	// table: i x j

	// Initialize seq: seq[i] = (i+1) % 4
	traverser(seq).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		seq[state] = static_cast<base>((i + 1) % 4);
	});

	// Initialize table to zeros
	traverser(table).for_each([=](auto state) {
		table[state] = num_t(0);
	});
}

/*
  Main computational kernel (Nussinov RNA folding DP).

  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
[[gnu::flatten, gnu::noinline]]
void kernel_nussinov(auto seq, auto table) {
	using namespace noarr;

	// table: i x j
	auto n_len = table | get_length<'i'>();
	int n = static_cast<int>(n_len);

#pragma scop
	// We use a traverser over dimension 'i' to control the outer loop.
	// The traverser iterates i in ascending order 0..n-1; we map it to a
	// descending index i_desc = n-1 - i_iter to match the original loop:
	// for (i = n-1; i >= 0; i--)
	traverser(table).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		int i_iter = static_cast<int>(get_index<'i'>(state_i));
		int i      = n - 1 - i_iter; // original loop index

		for (int j = i + 1; j < n; ++j) {

			// table[i][j] = max(table[i][j], table[i][j-1]);
			if (j - 1 >= 0) {
				auto state_ij    = noarr::idx<'i','j'>(i, j);
				auto candidate   = table[noarr::idx<'i','j'>(i, j - 1)];
				if (table[state_ij] < candidate)
					table[state_ij] = candidate;
			}

			// table[i][j] = max(table[i][j], table[i+1][j]);
			if (i + 1 < n) {
				auto state_ij    = noarr::idx<'i','j'>(i, j);
				auto candidate   = table[noarr::idx<'i','j'>(i + 1, j)];
				if (table[state_ij] < candidate)
					table[state_ij] = candidate;
			}

			// if (j-1>=0 && i+1<n) { ... }
			if (j - 1 >= 0 && i + 1 < n) {
				auto state_ij      = noarr::idx<'i','j'>(i, j);
				auto base_candidate = table[noarr::idx<'i','j'>(i + 1, j - 1)];

				// don't allow adjacent elements to bond
				if (i < j - 1) {
					auto match_score = match_base(
						seq[noarr::idx<'i'>(i)],
						seq[noarr::idx<'i'>(j)]
					);
					auto candidate = base_candidate + match_score;
					if (table[state_ij] < candidate)
						table[state_ij] = candidate;
				} else {
					if (table[state_ij] < base_candidate)
						table[state_ij] = base_candidate;
				}
			}

			// for (k = i+1; k < j; k++)
			for (int k = i + 1; k < j; ++k) {
				auto state_ij  = noarr::idx<'i','j'>(i, j);
				auto candidate = table[noarr::idx<'i','j'>(i, k)]
				               + table[noarr::idx<'i','j'>(k + 1, j)];
				if (table[state_ij] < candidate)
					table[state_ij] = candidate;
			}
		}
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// data structures
	auto seq = noarr::bag(noarr::scalar<base>()   ^ tuning.seq_layout   ^ set_lengths);
	auto table = noarr::bag(noarr::scalar<num_t>() ^ tuning.table_layout ^ set_lengths);

	// initialize data
	init_array(seq.get_ref(), table.get_ref());

	// measure kernel execution time
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_nussinov(seq.get_ref(), table.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' so rows are printed contiguously
		noarr::serialize_data(std::cerr, table.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
