#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "nussinov.hpp"

using num_t = DATA_TYPE;
using base  = char;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();

struct tuning {
	// 1D sequence: index 'i'
	static constexpr auto seq_layout   = i_vec;
	// 2D table: indices 'i', 'j'
	static constexpr auto table_layout = j_vec ^ i_vec; // layout choice is free; dims are 'i' and 'j'
} tuning;

// helpers corresponding to the C macros
inline num_t max_score(num_t s1, num_t s2) {
	return (s1 >= s2) ? s1 : s2;
}

inline num_t match_score(base b1, base b2) {
	// original: ((b1)+(b2)) == 3 ? 1 : 0
	return ((b1 + b2) == 3) ? num_t(1) : num_t(0);
}

// Array initialization
void init_array(auto seq, auto table) {
	using namespace noarr;

	// seq[i] = (base)((i+1) % 4)
	traverser(seq).for_each([&](auto state) {
		auto i = get_index<'i'>(state);
		seq[state] = static_cast<base>((i + 1) % 4);
	});

	// table[i][j] = 0
	traverser(table).for_each([&](auto state) {
		table[state] = num_t(0);
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_nussinov(auto seq, auto table) {
	using namespace noarr;

	// table: i x j (square: N x N)
	// seq:   i
	auto n = table | get_length<'i'>();

	// Synthetic structures to drive traversers over indices:
	//  - (l, i) pairs, where l is subsequence length (j - i)
	//  - k index for splitting
	auto li_struct = noarr::scalar<char>() ^ l_vec ^ i_vec;
	auto li_sized  = li_struct ^ noarr::set_length<'l'>(n) ^ noarr::set_length<'i'>(n);

	auto k_struct  = noarr::scalar<char>() ^ k_vec;
	auto k_sized   = k_struct ^ noarr::set_length<'k'>(n);

#pragma scop
	// Process increasing subsequence length l = j - i (l = 1 .. n-1)
	traverser(li_sized).template for_dims<'l'>([&](auto trav_l) {
		auto state_l = trav_l.state();
		std::size_t l = get_index<'l'>(state_l);

		if (l == 0 || l >= n)
			return; // skip length 0 and out-of-range

		// For given l, iterate i, compute j = i + l, only if j < n
		trav_l.template for_dims<'i'>([&](auto trav_i) {
			auto state_li = trav_i.state();
			std::size_t i = get_index<'i'>(state_li);
			std::size_t j = i + l;

			if (j >= n)
				return;

			auto s_ij = noarr::idx<'i','j'>(i, j);

			// Start from current table[i][j]
			num_t best = table[s_ij];

			// if (j-1 >= 0) table[i][j] = max(table[i][j], table[i][j-1]);
			if (j > 0) {
				auto s_i_jm1 = noarr::idx<'i','j'>(i, j - 1);
				best = max_score(best, table[s_i_jm1]);
			}

			// if (i+1 < N) table[i][j] = max(table[i][j], table[i+1][j]);
			if (i + 1 < n) {
				auto s_ip1_j = noarr::idx<'i','j'>(i + 1, j);
				best = max_score(best, table[s_ip1_j]);
			}

			// if (j-1 >= 0 && i+1 < N) {
			//   if (i < j-1)
			//     table[i][j] = max(table[i][j], table[i+1][j-1] + match(seq[i], seq[j]));
			//   else
			//     table[i][j] = max(table[i][j], table[i+1][j-1]);
			// }
			if (j > 0 && i + 1 < n) {
				auto s_ip1_jm1 = noarr::idx<'i','j'>(i + 1, j - 1);
				num_t candidate = table[s_ip1_jm1];

				// don't allow adjacent elements to bond
				if (i < j - 1) {
					base si = seq[noarr::idx<'i'>(i)];
					base sj = seq[noarr::idx<'i'>(j)];
					candidate = candidate + match_score(si, sj);
				}

				best = max_score(best, candidate);
			}

			// for (k = i+1; k < j; k++)
			//   table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
			traverser(k_sized).for_each([&](auto state_k) {
				std::size_t k = get_index<'k'>(state_k);

				if (k <= i || k >= j)
					return;

				auto s_i_k   = noarr::idx<'i','j'>(i,     k);
				auto s_kp1_j = noarr::idx<'i','j'>(k + 1, j);

				num_t candidate = table[s_i_k] + table[s_kp1_j];
				best = max_score(best, candidate);
			});

			table[s_ij] = best;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// set lengths for structures
	auto set_lengths_table = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_length_seq    = noarr::set_length<'i'>(n);

	// data containers
	auto seq   = noarr::bag(noarr::scalar<base>()   ^ tuning.seq_layout   ^ set_length_seq);
	auto table = noarr::bag(noarr::scalar<num_t>()  ^ tuning.table_layout ^ set_lengths_table);

	// initialize data
	init_array(seq.get_ref(), table.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
