#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, N, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions (problem size, etc.)
#include "nussinov.hpp"

using num_t = DATA_TYPE;
using base = char;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	DEFINE_PROTO_STRUCT(seq_layout,  i_vec);        // seq: i
	DEFINE_PROTO_STRUCT(table_layout, j_vec ^ i_vec); // table: i x j (row-major)
} tuning;

inline num_t match(base b1, base b2) noexcept {
	return ((b1 + b2) == 3) ? num_t(1) : num_t(0);
}

inline num_t max_score(num_t s1, num_t s2) noexcept {
	return (s1 >= s2) ? s1 : s2;
}

// Array initialization
void init_array(auto seq, auto table) {
	using namespace noarr;

	// initialize seq[i] = (base)((i+1) % 4)
	traverser(seq).for_each([&](auto state) {
		auto i = get_index<'i'>(state);
		seq[state] = static_cast<base>((i + 1) % 4);
	});

	// initialize table[i][j] = 0
	traverser(table).for_each([&](auto state) {
		table[state] = num_t(0);
	});
}

// computation kernel (Nussinov RNA folding)
[[gnu::flatten, gnu::noinline]]
void kernel_nussinov(auto seq, auto table) {
	using namespace noarr;

	// problem size from structure
	std::size_t n = table | get_length<'i'>();

	// iteration domains (no data, just for traverser control)
	auto di_domain = noarr::scalar<char>() ^ noarr::vector<'i'>(n) ^ noarr::vector<'d'>(n);
	auto k_domain  = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

#pragma scop
	// iterate over "distance" d = j - i (outer), then i (inner)
	// j = i + d, operate only when 0 <= i < j < n
	noarr::traverser(di_domain).for_each([&](auto state_di) {
		auto i = noarr::get_index<'i'>(state_di);
		auto d = noarr::get_index<'d'>(state_di);

		if (d == 0) return;          // need j > i
		std::size_t j = i + d;
		if (j >= n) return;          // outside upper triangle

		// table[i][j]
		auto s_ij = noarr::idx<'i', 'j'>(i, j);
		num_t cur = table[s_ij];

		// if (j-1 >= 0) table[i][j] = max(table[i][j], table[i][j-1]);
		// here j >= 1 always (d >= 1, i >= 0)
		auto s_i_jm1 = noarr::idx<'i', 'j'>(i, j - 1);
		cur = max_score(cur, table[s_i_jm1]);

		// if (i+1 < n) table[i][j] = max(table[i][j], table[i+1][j]);
		if (i + 1 < n) {
			auto s_ip1_j = noarr::idx<'i', 'j'>(i + 1, j);
			cur = max_score(cur, table[s_ip1_j]);
		}

		// if (j-1 >= 0 && i+1 < n) { ... }
		if (i + 1 < n) {
			auto s_ip1_jm1 = noarr::idx<'i', 'j'>(i + 1, j - 1);

			// don't allow adjacent elements to bond
			if (i < j - 1) {
				base bi = seq[noarr::idx<'i'>(i)];
				base bj = seq[noarr::idx<'i'>(j)];
				cur = max_score(cur, table[s_ip1_jm1] + match(bi, bj));
			} else {
				cur = max_score(cur, table[s_ip1_jm1]);
			}
		}

		// for (k = i+1; k < j; k++)
		noarr::traverser(k_domain).for_each([&](auto sk) {
			auto k = noarr::get_index<'k'>(sk);
			if (k <= i || k >= j) return;

			num_t left  = table[noarr::idx<'i', 'j'>(i, k)];
			num_t right = table[noarr::idx<'i', 'j'>(k + 1, j)];
			cur = max_score(cur, left + right);
		});

		table[s_ij] = cur;
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// common length spec for i and j
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// seq: length n, indexed by 'i'
	auto seq = noarr::bag(noarr::scalar<base>() ^ tuning.seq_layout ^ set_lengths);

	// table: n x n, indexed by 'i' (rows) and 'j' (cols)
	auto table = noarr::bag(noarr::scalar<num_t>() ^ tuning.table_layout ^ set_lengths);

	// initialize data
	init_array(seq.get_ref(), table.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_nussinov(seq.get_ref(), table.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, table.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
